function validate([s]) {
  if (typeof s !== 'string' || s.length === 0) return 's must be a non-empty string.';
  if (/[^0-9\[\],-]/.test(s)) return 's may contain only digits, square brackets, commas and minus signs.';
  const bad = 's must be a valid nested list such as 324 or [1,[2,-3],[]], with no leading zeros.';
  const integer = /-?(?:0|[1-9]\d*)/y;
  let i = 0;
  let depth = 0;
  let last = 'start';
  while (i < s.length) {
    const ch = s[i];
    if (ch === '[') {
      if (last === 'value') return bad;
      depth++;
      if (depth > 200) return 'This app accepts at most 200 levels of nested brackets.';
      last = 'open';
      i++;
    } else if (ch === ']') {
      if (depth === 0 || last === 'comma') return bad;
      depth--;
      last = 'value';
      i++;
    } else if (ch === ',') {
      if (depth === 0 || last !== 'value') return bad;
      last = 'comma';
      i++;
    } else {
      if (last === 'value') return bad;
      integer.lastIndex = i;
      const match = integer.exec(s);
      if (!match || match[0] === '-0') return bad;
      if (Math.abs(Number(match[0])) > 1e6) return 'Every integer must be between -10^6 and 10^6.';
      i += match[0].length;
      last = 'value';
    }
    if (depth === 0 && i < s.length) return bad;
  }
  if (depth !== 0 || last !== 'value') return bad;
  return null;
}

