function adapt(input, solve, kit) {
  // LeetCode provides NestedInteger; this is the same API.
  class NestedInteger {
    constructor(value) {
      this._integer = value === undefined ? null : value;
      this._list = value === undefined ? [] : null;
    }
    isInteger() { return this._list === null; }
    getInteger() { return this._list === null ? this._integer : null; }
    setInteger(value) { this._integer = value; this._list = null; }
    add(elem) {
      if (this._list === null) { this._list = []; this._integer = null; }
      this._list.push(elem);
    }
    getList() { return this._list; }
  }
  globalThis.NestedInteger = NestedInteger;
  const result = solve(input[0]);
  let seen = 0;
  const toJson = item => {
    if (!(item instanceof NestedInteger)) throw new Error('Return a NestedInteger object.');
    if (++seen > 30000) throw new Error('The returned NestedInteger is too large or contains a cycle.');
    return item.isInteger() ? item.getInteger() : item.getList().map(toJson);
  };
  return toJson(result);
}

