function deserialize(s) {
  if (s[0] !== '[') {
    return new NestedInteger(Number(s));
  }

  const stack = [];
  let digits = '';

  for (const ch of s) {
    if (ch === '[') {
      stack.push(new NestedInteger());
    } else if (ch === '-' || (ch >= '0' && ch <= '9')) {
      digits += ch;
    } else {
      if (digits !== '') {
        stack[stack.length - 1].add(new NestedInteger(Number(digits)));
        digits = '';
      }
      if (ch === ']' && stack.length > 1) {
        const finished = stack.pop();
        stack[stack.length - 1].add(finished);
      }
    }
  }
  return stack[0];
}

