function deserialize(s) {
  // The encoding is valid JSON, so let JSON.parse do the parsing and convert the result.
  const build = value => {
    if (typeof value === 'number') return new NestedInteger(value);
    const list = new NestedInteger();
    for (const item of value) list.add(build(item));
    return list;
  };
  return build(JSON.parse(s));
}

