function generate(rand, size) {
  const value = () => {
    const magnitude = rand() < 0.5 ? Math.floor(rand() * 1000001) : Math.floor(rand() * 20);
    return magnitude !== 0 && rand() < 0.35 ? -magnitude : magnitude;
  };
  if (size === 'small') {
    if (rand() < 0.15) return [String(value())];
    const build = depth => {
      if (depth >= 4 || (depth > 0 && rand() < 0.45)) return value();
      return Array.from({ length: Math.floor(rand() * 4) }, () => build(depth + 1));
    };
    return [JSON.stringify(build(0))];
  }
  for (;;) {
    let budget = 1000;
    const build = depth => {
      if (budget <= 0 || depth >= 8 || rand() < 0.5) { budget--; return value(); }
      const items = [];
      const count = Math.floor(rand() * 7);
      for (let k = 0; k < count && budget > 0; k++) items.push(build(depth + 1));
      return items;
    };
    const root = [];
    while (budget > 0) root.push(build(1));
    const s = JSON.stringify(root);
    if (s.length <= 10000) return [s];
  }
}
